import { mapBaseUserToFront } from '@apps/Account/@mappers/user.mappers';
import { getSQLDate } from '@helpers/dateHelper';

import { mapBaseWorkoutToFront } from './workouts.mapper';
import {
  IWorkoutTargetAddDTO,
  IWorkoutTargetBaseDTO,
  IWorkoutTargetDTO,
  IWorkoutTargetStatDTO,
  IWorkoutTargetUpdateDTO,
} from '../@types/DTO/workoutsTargets.dto.types';
import {
  IWorkoutTarget,
  IWorkoutTargetBase,
  IWorkoutTargetStat,
} from '../@types/workoutsTargets.types';

export const mapWorkoutTargetBaseToFront = (
  backData: IWorkoutTargetBaseDTO,
): IWorkoutTargetBase => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.description,
    date_start: new Date(backData.date_start),
    date_finish: new Date(backData.date_finish),
    is_public: backData.is_public === '1',
    type:
      backData.workout_type && backData.workout_type_name
        ? {
            id: +backData.workout_type,
            name: backData.workout_type_name,
          }
        : null,
  };
};

export const mapWorkoutTargetToFront = (backData: IWorkoutTargetDTO): IWorkoutTarget => {
  return {
    ...mapWorkoutTargetBaseToFront(backData),
    date_create: new Date(backData.date_create),
    date_update: backData.date_update ? new Date(backData.date_update) : null,
    author: {
      id: +backData.author_id,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
    hiking: backData.hiking_id
      ? {
          id: +backData.hiking_id,
          name: backData.hiking_name,
          ava: backData.hiking_ava,
          start: new Date(backData.hiking_start),
          finish: new Date(backData.hiking_finish),
        }
      : null,

    distance: backData.distance ? +backData.distance : null,
    alt_ascent: backData.alt_ascent ? +backData.alt_ascent : null,
    alt_descent: backData.alt_descent ? +backData.alt_descent : null,
    speed_max: backData.speed_max ? +backData.speed_max : null,
    speed_min: backData.speed_min ? +backData.speed_min : null,
    speed_avg: backData.speed_avg ? +backData.speed_avg : null,
    hr_max: backData.hr_max ? +backData.hr_max : null,
    hr_min: backData.hr_min ? +backData.hr_min : null,
    hr_avg: backData.hr_avg ? +backData.hr_avg : null,
    time_moving: backData.time_mooving ? +backData.time_mooving : null,
  };
};

export const marWorkoutTargetToAddDTO = (workoutTarget: IWorkoutTarget): IWorkoutTargetAddDTO => {
  return {
    name: workoutTarget.name,
    description: workoutTarget.description,
    date_start: getSQLDate(workoutTarget.date_start),
    date_finish: getSQLDate(workoutTarget.date_finish),
    distance: workoutTarget.distance,
    alt_ascent: workoutTarget.alt_ascent,
    alt_descent: workoutTarget.alt_descent,
    speed_max: workoutTarget.speed_max,
    speed_min: workoutTarget.speed_min,
    speed_avg: workoutTarget.speed_avg,
    hr_max: workoutTarget.hr_max,
    hr_min: workoutTarget.hr_min,
    hr_avg: workoutTarget.hr_avg,
    time_mooving: workoutTarget.time_moving,
    workout_type: workoutTarget.type?.id ?? null,
    is_public: workoutTarget.is_public ? 1 : 0,
    id_hiking: workoutTarget.hiking?.id ?? null,
  };
};

export const marWorkoutTargetToUpdateDTO = (
  workoutTarget: IWorkoutTarget,
): IWorkoutTargetUpdateDTO => {
  return { ...marWorkoutTargetToAddDTO(workoutTarget), id: workoutTarget.id };
};

export const mapWorkoutTargetStatToFront = (
  backData: IWorkoutTargetStatDTO,
): IWorkoutTargetStat => {
  return {
    user: mapBaseUserToFront(backData.user),
    statistic: !backData.statistic
      ? null
      : {
          first_workout_date: new Date(backData.statistic.first_workout_date),
          max_workout_date: new Date(backData.statistic.max_workout_date),

          distance: Number(backData.statistic.distance),
          alt_ascent: Number(backData.statistic.alt_ascent),
          alt_descent: Number(backData.statistic.alt_descent),
          alt_max: Number(backData.statistic.alt_max),
          alt_min: Number(backData.statistic.alt_min),
          alt_avg: Number(backData.statistic.alt_avg),
          speed_max: Number(backData.statistic.speed_max),
          speed_min: Number(backData.statistic.speed_min),
          speed_avg: Number(backData.statistic.speed_avg),
          hr_max: Number(backData.statistic.hr_max),
          hr_min: Number(backData.statistic.hr_min),
          hr_avg: Number(backData.statistic.hr_avg),
          time_moving: Number(backData.statistic.time_mooving),

          workouts: backData.statistic.workouts.map(mapBaseWorkoutToFront),
        },
  };
};
